export const ALL_PERFUME_HOUSES = [...ARABIC_HOUSES, ...DESIGNER_NICHE_HOUSES];

/**
 * Searches across all perfume database presets by perfume name, house, or keywords with strict fuzzy matching & relevance scoring
 */
export function searchPerfumePresets(queryText: string): PerfumePreset[] {
  const q = queryText.toLowerCase().trim();
  if (!q || q.length < 2) return [];

  const scoredResults: { perfume: PerfumePreset; score: number }[] = [];
  const added = new Set<string>();

  // Word token list
  const queryTokens = q.split(/[\s-_]+/).filter((t) => t.length >= 2);

  ALL_PERFUME_HOUSES.forEach((house) => {
    const houseNameLower = house.name.toLowerCase();
    house.famousPerfumes.forEach((perfume) => {
      const pName = perfume.name.toLowerCase();
      const pBrand = perfume.brand.toLowerCase();
      const pFullName = `${pBrand} ${pName}`.toLowerCase();
      let score = 0;

      // 1. Exact Full Matches
      if (pName === q || pFullName === q) {
        score += 2000;
      } else if (pName.startsWith(q) || pFullName.startsWith(q)) {
        score += 800;
      } else if (new RegExp(`\\b${escapeRegExp(q)}\\b`, "i").test(pName) || new RegExp(`\\b${escapeRegExp(q)}\\b`, "i").test(pFullName)) {
        score += 600;
      }

      // 2. Brand Match Bonus
      const brandInQuery = queryTokens.some((t) => pBrand.includes(t) || houseNameLower.includes(t));
      if (brandInQuery) {
        score += 250;
      }

      // 3. Strict Whole-Word Token Matching
      let matchedCount = 0;
      for (const token of queryTokens) {
        const tokenRegex = new RegExp(`\\b${escapeRegExp(token)}\\b`, "i");
        const matchesName = tokenRegex.test(pName);
        const matchesBrand = tokenRegex.test(pBrand);
        const matchesKeyword = perfume.keywords?.some((k) => tokenRegex.test(k.toLowerCase())) || false;

        if (matchesName || matchesBrand || matchesKeyword) {
          matchedCount++;
        }
      }

      if (queryTokens.length > 1) {
        if (matchedCount === queryTokens.length) {
          score += 500;
        } else if (matchedCount >= queryTokens.length * 0.7 && brandInQuery) {
          score += 200;
        }
      } else if (queryTokens.length === 1 && matchedCount === 1) {
        score += 150;
      }

      // 4. Keyword exact matches
      if (perfume.keywords && perfume.keywords.some((k) => k.toLowerCase() === q)) {
        score += 300;
      }

      // 5. SKU & UPC/EAN exact matches
      if (perfume.sku && perfume.sku.toLowerCase() === q) score += 3000;
      if (perfume.upc && perfume.upc.toLowerCase() === q) score += 3000;
      if (perfume.barcode && perfume.barcode.toLowerCase() === q) score += 3000;

      if (score >= 150 && !added.has(perfume.name + perfume.brand)) {
        scoredResults.push({ perfume, score });
        added.add(perfume.name + perfume.brand);
      }
    });
  });

  scoredResults.sort((a, b) => b.score - a.score);
  return scoredResults.map((r) => r.perfume);
}

function escapeRegExp(string: string) {
  return string.replace(/[.*+?^$${}()|[\]\\]/g, "\\$&");
}


