export function getEnrichedPerfumeData(name: string, brand?: string): Partial<PerfumePreset> | null {
  if (!name) return null;
  const cleanName = name.trim();
  const cleanBrand = (brand || "").trim();
  const nLower = cleanName.toLowerCase();

  // 1. Direct dictionary check
  for (const [key, val] of Object.entries(EXTRA_DUPES_MAP)) {
    if (nLower.includes(key)) {
      return {
        name: cleanName,
        brand: cleanBrand || "Lattafa",
        brandType: "arabic",
        shortDescription: val.desc,
        description: val.desc,
        inspiredBy: val.inspiredBy,
        originalBrand: val.originalBrand,
        relationshipType: "Inspirado / dupe",
        estimatedSimilarity: val.sim,
        isOneToOne: "No",
        notes: val.notes,
        concentration: "Eau de Parfum (EDP)",
        gender: "Unisex",
        measure: "100 ml / 3.4 fl oz",
      };
    }
  }

  // 2. Search presets
  const presets = searchPerfumePresets(`${cleanBrand} ${cleanName}`);
  const foundPreset = presets && presets.length > 0 ? presets[0] : null;

  if (foundPreset) {
    return {
      name: foundPreset.name,
      brand: foundPreset.brand,
      brandType: foundPreset.brandType,
      shortDescription: foundPreset.shortDescription,
      description: foundPreset.description,
      inspiredBy: foundPreset.inspiredBy,
      originalBrand: foundPreset.originalBrand,
      relationshipType: foundPreset.relationshipType,
      estimatedSimilarity: foundPreset.estimatedSimilarity,
      isOneToOne: foundPreset.isOneToOne,
      notes: foundPreset.notes,
      concentration: foundPreset.concentration,
      gender: foundPreset.gender,
      measure: foundPreset.measure,
      upc: foundPreset.upc || foundPreset.barcode,
      barcode: foundPreset.barcode || foundPreset.upc,
    };
  }

  return null;
}
